function countBalanced(low: number, high: number): number {
  let count = 0;
  for (let x = low; x <= high; x++) {
    const s = String(x);
    if (s.length % 2 === 1) continue;
    const k = s.length / 2;
    let diff = 0;
    for (let i = 0; i < k; i++) diff += Number(s[i]) - Number(s[i + k]);
    if (diff === 0) count++;
  }
  return count;
}

