class Solution:
    def countBalanced(self, low: int, high: int) -> int:
        count = 0
        for x in range(low, high + 1):
            s = str(x)
            if len(s) % 2:
                continue
            k = len(s) // 2
            if sum(map(int, s[:k])) == sum(map(int, s[k:])):
                count += 1
        return count

