function countBalanced(low: number, high: number): number {
  let count = 0;
  for (let x = low; x <= high; x++) {
    if (x >= 10 && x < 100) {
      if (x % 11 === 0) count++; // both digits equal
    } else if (x >= 1000 && x < 10000) {
      const left = Math.floor(x / 1000) + (Math.floor(x / 100) % 10);
      const right = (Math.floor(x / 10) % 10) + (x % 10);
      if (left === right) count++;
    }
  }
  return count;
}

